41: export async function requireMember(ctx: Ctx, projectId: Id<"projects">, sessionToken: string) {
42:   const user = await requireUser(ctx, sessionToken);
43:   const project = await ctx.db.get(projectId);
44:   if (!project) throw new Error("Project not found");
45:   const member = await projectMember(ctx, project, user);
46:   if (member) return { member, user, project };
47:   throw new Error("No active project access");
