50: // Workspace admins see every project; everyone else needs explicit membership.
51: // A project role can never bypass a read-only workspace role.
52: export async function projectMember(ctx: Ctx, project: Doc<"projects">, user: Pick<Doc<"users">, "_id" | "email">) {
53:   const team = project.teamId ? await getActiveTeamMember(ctx, project.teamId, user.email) : null;
54:   if (project.teamId && (!team || (team.userId && team.userId !== user._id))) return null;
55:   if (team && ["owner", "admin"].includes(team.role)) return team;
56:   const member = await getActiveMember(ctx, project._id, user.email);
57:   if (!member || (member.userId && member.userId !== user._id)) return null;
58:   return team?.role === "viewer" ? { ...member, role: "viewer" as const } : member;

